CREATE TABLE IF NOT EXISTS "test_migrations" (
    "id" INTEGER PRIMARY KEY, "name" TEXT NOT NULL, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
)

CREATE TABLE IF NOT EXISTS "users" (
    "id" INTEGER PRIMARY KEY, "username" TEXT UNIQUE, "is_active" BOOLEAN DEFAULT 1
)

CREATE TABLE IF NOT EXISTS "posts" (
    "id" INTEGER PRIMARY KEY, "title" TEXT, "author_id" INTEGER, "is_published" BOOLEAN DEFAULT 0
)

CREATE TABLE IF NOT EXISTS "users" (
    "id" SERIAL PRIMARY KEY, "username" VARCHAR(100) UNIQUE NOT NULL, "email" VARCHAR(255) UNIQUE NOT NULL, "age" INTEGER NOT NULL, "salary" DECIMAL(10,2) NOT NULL, "is_active" BOOLEAN DEFAULT TRUE, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "metadata" JSONB, "tags" TEXT[]
)

CREATE TABLE IF NOT EXISTS "orders" (
    "id" SERIAL PRIMARY KEY, "user_id" INTEGER NOT NULL, "product_name" VARCHAR(200) NOT NULL, "quantity" INTEGER NOT NULL, "price" DECIMAL(10,2) NOT NULL, "total_amount" DECIMAL(10,2) NOT NULL, "order_date" TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "status" VARCHAR(50) DEFAULT 'pending'
)

CREATE TABLE IF NOT EXISTS "products" (
    "id" SERIAL PRIMARY KEY, "name" VARCHAR(200) NOT NULL, "category" VARCHAR(100) NOT NULL, "price" DECIMAL(10,2) NOT NULL, "stock" INTEGER NOT NULL, "rating" DECIMAL(3,2), "tags" TEXT[], "metadata" JSONB
)

CREATE TABLE IF NOT EXISTS "test_users" (
    "id" SERIAL PRIMARY KEY, "username" VARCHAR(100) UNIQUE NOT NULL, "email" VARCHAR(255) UNIQUE NOT NULL, "age" INTEGER NOT NULL, "salary" DECIMAL(10,2) NOT NULL, "tags" TEXT[], "metadata" JSONB
)
